package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// FromJSON parses a JSON string and returns a Theme.
// If parsing fails, returns the default theme with an error.
//
// Since: 2.5
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// If parsing fails, returns the default theme with an error.
//
// Since: 2.5
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw map[string]interface{}
	if err := json.NewDecoder(r).Decode(&raw); err != nil {
		return DefaultTheme(), err
	}

	jt := &jsonTheme{
		colors:      make(map[fyne.ThemeColorName]color.Color),
		colorsDark:  make(map[fyne.ThemeColorName]color.Color),
		colorsLight: make(map[fyne.ThemeColorName]color.Color),
		sizes:       make(map[fyne.ThemeSizeName]float32),
		fonts:       make(map[fyne.TextStyle]fyne.Resource),
		icons:       make(map[fyne.ThemeIconName]fyne.Resource),
	}

	// Parse colors
	if colors, ok := raw["Colors"].(map[string]interface{}); ok {
		for name, value := range colors {
			if hexStr, ok := value.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					jt.colors[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse dark variant colors
	if colorsDark, ok := raw["Colors-dark"].(map[string]interface{}); ok {
		for name, value := range colorsDark {
			if hexStr, ok := value.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					jt.colorsDark[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse light variant colors
	if colorsLight, ok := raw["Colors-light"].(map[string]interface{}); ok {
		for name, value := range colorsLight {
			if hexStr, ok := value.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					jt.colorsLight[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse sizes
	if sizes, ok := raw["Sizes"].(map[string]interface{}); ok {
		for name, value := range sizes {
			if floatVal, ok := value.(float64); ok {
				jt.sizes[fyne.ThemeSizeName(name)] = float32(floatVal)
			}
		}
	}

	// Parse fonts
	if fonts, ok := raw["Fonts"].(map[string]interface{}); ok {
		for styleName, value := range fonts {
			if uriStr, ok := value.(string); ok {
				if res, err := fyne.LoadResourceFromURI(storage.NewURI(uriStr)); err == nil {
					var style fyne.TextStyle
					switch styleName {
					case "regular":
						style = fyne.TextStyle{}
					case "bold":
						style = fyne.TextStyle{Bold: true}
					case "italic":
						style = fyne.TextStyle{Italic: true}
					case "boldItalic":
						style = fyne.TextStyle{Bold: true, Italic: true}
					case "monospace":
						style = fyne.TextStyle{Monospace: true}
					default:
						continue
					}
					jt.fonts[style] = res
				}
			}
		}
	}

	// Parse icons
	if icons, ok := raw["Icons"].(map[string]interface{}); ok {
		for name, value := range icons {
			if uriStr, ok := value.(string); ok {
				if res, err := fyne.LoadResourceFromURI(storage.NewURI(uriStr)); err == nil {
					jt.icons[fyne.ThemeIconName(name)] = res
				}
			}
		}
	}

	return jt, nil
}

// parseHexColor parses a hex color string in various formats:
// - 3 digits: "abc" -> #aabbcc
// - 4 digits: "abcd" -> #aabbccdd
// - 6 digits: "a1b2c3" -> #a1b2c3
// - 8 digits: "a1b2c3f4" -> #a1b2c3f4
// All formats support optional "#" prefix
func parseHexColor(hex string) (color.Color, error) {
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8
	a = 0xff // default alpha

	switch len(hex) {
	case 3:
		// RGB: each digit is doubled
		vals, err := parseHexDigits(hex, 3)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0] | (vals[0] << 4)
		g = vals[1] | (vals[1] << 4)
		b = vals[2] | (vals[2] << 4)
	case 4:
		// RGBA: each digit is doubled
		vals, err := parseHexDigits(hex, 4)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0] | (vals[0] << 4)
		g = vals[1] | (vals[1] << 4)
		b = vals[2] | (vals[2] << 4)
		a = vals[3] | (vals[3] << 4)
	case 6:
		// RRGGBB
		val, err := strconv.ParseUint(hex, 16, 32)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
		r = uint8(val >> 16)
		g = uint8(val >> 8)
		b = uint8(val)
	case 8:
		// RRGGBBAA
		val, err := strconv.ParseUint(hex, 16, 32)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
		r = uint8(val >> 24)
		g = uint8(val >> 16)
		b = uint8(val >> 8)
		a = uint8(val)
	default:
		return color.Transparent, fmt.Errorf("invalid hex color length: %s", hex)
	}

	return color.RGBA{R: r, G: g, B: b, A: a}, nil
}

// parseHexDigits parses n hex digits and returns their values
func parseHexDigits(hex string, n int) ([]uint8, error) {
	if len(hex) != n {
		return nil, fmt.Errorf("expected %d hex digits, got %d", n, len(hex))
	}

	vals := make([]uint8, n)
	for i := 0; i < n; i++ {
		val, err := strconv.ParseUint(string(hex[i]), 16, 8)
		if err != nil {
			return nil, fmt.Errorf("invalid hex digit: %c", hex[i])
		}
		vals[i] = uint8(val)
	}
	return vals, nil
}

type jsonTheme struct {
	colors      map[fyne.ThemeColorName]color.Color
	colorsDark  map[fyne.ThemeColorName]color.Color
	colorsLight map[fyne.ThemeColorName]color.Color
	sizes       map[fyne.ThemeSizeName]float32
	fonts       map[fyne.TextStyle]fyne.Resource
	icons       map[fyne.ThemeIconName]fyne.Resource
}

func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	if variant == VariantDark {
		if c, ok := t.colorsDark[name]; ok {
			return c
		}
	} else if variant == VariantLight {
		if c, ok := t.colorsLight[name]; ok {
			return c
		}
	}

	// Check generic colors
	if c, ok := t.colors[name]; ok {
		return c
	}

	// Fall back to default theme
	return DefaultTheme().Color(name, variant)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	if res, ok := t.fonts[style]; ok {
		return res
	}
	return DefaultTheme().Font(style)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if res, ok := t.icons[name]; ok {
		return res
	}
	return DefaultTheme().Icon(name)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if val, ok := t.sizes[name]; ok {
		return val
	}
	return DefaultTheme().Size(name)
}

