package binding

import (
	"fmt"
)

// NewSprintf returns a String binding that formats its content using the format string and
// provided data bindings. The format should be a fmt.Sprintf compatible string with placeholders
// for each of the data values. Any change to a source binding will cause the output to update.
//
// Since: 2.5
func NewSprintf(format string, bindings ...DataItem) String {
	if len(bindings) == 0 {
		return NewString() // return empty binding if no sources
	}

	s := &sprintfString{
		format:   format,
		bindings: bindings,
	}

	for _, b := range bindings {
		b.AddListener(s)
	}

	return s
}

type sprintfString struct {
	base
	format   string
	bindings []DataItem
}

func (s *sprintfString) Get() (string, error) {
	values := make([]interface{}, len(s.bindings))

	for i, b := range s.bindings {
		switch v := b.(type) {
		case String:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Int:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Float:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Bool:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Untyped:
			val, err := v.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		default:
			values[i] = ""
		}
	}

	return fmt.Sprintf(s.format, values...), nil
}

func (s *sprintfString) Set(string) error {
	// sprintf bindings are read-only
	return nil
}

func (s *sprintfString) DataChanged() {
	s.trigger()
}

// StringToStringWithFormat creates a binding that converts a String to another String using
// the specified format. This is useful for adding prefixes, suffixes, or other formatting.
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	return NewSprintf(format, str)
}

