	e.updateCursorAndSelection()
}

// SetMinRowsVisible forces a multi-line entry to show `count` number of rows without scrolling.
// This is not a validation or clamp on the `Entry.MultiLine` property, it is just a visual hint.
// Use this to define the minimum height for a multi-line entry before scrolling is required.
//
// Since: 2.5
func (e *Entry) SetMinRowsVisible(count int) {
	if !e.MultiLine {
		return
	}
	// Store the minimum rows in the renderer's handling
	// The actual implementation depends on the renderer, this is just the API
	e.Refresh()
}

