package validation

import (
	"errors"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a new validator that checks if the input string is contained in the provided list.
// The validator will return nil if the input matches one of the allowed strings, otherwise returns an error.
//
// Since: 2.5
func NewAllStrings(valid []string) fyne.StringValidator {
	return func(text string) error {
		for _, v := range valid {
			if text == v {
				return nil
			}
		}
		return errors.New("input does not match any allowed value")
	}
}

